import { createRequire } from 'node:module';
import { chromium } from 'playwright';

const require = createRequire(import.meta.url);
const axePath = require.resolve('axe-core/axe.min.js');
const html = await fs.readFile(new URL('./index.html', import.meta.url), 'utf8');

const browser = await chromium.launch({
  executablePath: '/usr/bin/chromium',
  headless: true
});

try {
  const page = await browser.newPage();
  await page.setContent(html, { waitUntil: 'load' });
  await page.addScriptTag({ path: axePath });
  const results = await page.evaluate(async () => await window.axe.run());
  const violations = results.violations.filter((v) => !v.tags?.includes('best-practice'));

  if (violations.length) {
    console.log(JSON.stringify(violations, null, 2));
    process.exitCode = 1;
  } else {
    const focusStates = [];

    await page.keyboard.press('Tab');
    focusStates.push(await page.evaluate(() => document.activeElement?.id || document.activeElement?.className || document.activeElement?.tagName));

    await page.keyboard.press('Tab');
    focusStates.push(await page.evaluate(() => document.activeElement?.id || document.activeElement?.className || document.activeElement?.tagName));

    await page.keyboard.press('ArrowDown');
    focusStates.push(await page.evaluate(() => ({
      active: document.activeElement?.id,
      checked: document.querySelector('input[name="notification-preference"]:checked')?.id
    })));

    await page.keyboard.press('ArrowDown');
    focusStates.push(await page.evaluate(() => ({
      active: document.activeElement?.id,
      checked: document.querySelector('input[name="notification-preference"]:checked')?.id
    })));

    const expected = [
      'skip-link',
      'notification-email',
      { active: 'notification-sms', checked: 'notification-sms' },
      { active: 'notification-push', checked: 'notification-push' }
    ];

    const ok = JSON.stringify(focusStates) === JSON.stringify(expected);
    if (!ok) {
      console.log(JSON.stringify({ focusStates, expected }, null, 2));
      process.exitCode = 1;
    } else {
      console.log('axe:pass keyboard:pass');
    }
  }
} finally {
  await browser.close();
}
