<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Notification Preferences</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #0b1220;
        --surface: #111a2e;
        --surface-2: #16233d;
        --border: #2b3b5f;
        --border-strong: #5b7cff;
        --text: #e8eefc;
        --muted: #a8b4d3;
        --accent: #7c9cff;
        --accent-2: #97a6ff;
        --focus: #f7c948;
        --shadow: 0 24px 60px rgba(0, 0, 0, 0.35);
      }

      * {
        box-sizing: border-box;
      }

      html {
        font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        background:
          radial-gradient(circle at top, rgba(92, 124, 255, 0.18), transparent 36%),
          linear-gradient(180deg, #09101d 0%, var(--bg) 100%);
        color: var(--text);
      }

      body {
        margin: 0;
        min-height: 100vh;
        color: var(--text);
      }

      .skip-link {
        position: absolute;
        left: 1rem;
