        text-decoration: none;
        font-weight: 600;
      }

      .skip-link:focus {
        top: 1rem;
        outline: 3px solid var(--focus);
        outline-offset: 3px;
      }

      .page {
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 2rem 1rem;
      }

      .card {
        width: min(100%, 44rem);
