      }

      .form-field {
        padding: 1.25rem;
        border: 1px solid rgba(122, 143, 198, 0.2);
        border-radius: 1.125rem;
        background: rgba(255, 255, 255, 0.02);
      }

      fieldset {
        margin: 0;
        padding: 0;
