      button:hover {
        filter: brightness(1.05);
      }

      button:focus-visible {
        outline: 3px solid var(--focus);
        outline-offset: 3px;
      }

      @media (max-width: 480px) {
        .page {
          padding: 1rem;
        }

        .card {
          border-radius: 1.1rem;
        }

        .form-field {
          padding: 1rem;
        }

        .actions {
          justify-content: normal;
        }

        button {
          width: 100%;
        }
      }

      @media (forced-colors: active) {
        .card,
        .form-field,
        .option,
        button {
          forced-color-adjust: auto;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main">Skip to main content</a>
    <div id="app">
      <main id="main" class="page">
        <section class="card" aria-labelledby="page-title">
          <h1 id="page-title">Notification preferences</h1>
          <p class="lede">Choose one way you would like to receive updates.</p>

          <form>
            <div class="form-field">
              <fieldset aria-describedby="notification-help">
                <legend>
                  How do you prefer to receive notifications?
                  <span class="required-mark" aria-hidden="true">*</span>
                </legend>
                <p id="notification-help" class="help-text">Select one option before sending the form.</p>
                <div class="options">
                  <label class="option" for="notification-email">
                    <input
                      id="notification-email"
                      type="radio"
                      name="notification-preference"
                      value="email"
                      required
                    >
                    <span>Email</span>
                  </label>
                  <label class="option" for="notification-sms">
                    <input
                      id="notification-sms"
                      type="radio"
                      name="notification-preference"
                      value="sms"
                      required
                    >
                    <span>SMS</span>
                  </label>
                  <label class="option" for="notification-push">
                    <input
                      id="notification-push"
                      type="radio"
                      name="notification-preference"
                      value="push"
                      required
                    >
                    <span>Push Notifications</span>
                  </label>
                </div>
              </fieldset>
            </div>

            <div class="actions">
              <button type="submit">Save preferences</button>
            </div>
          </form>
        </section>
      </main>
    </div>

    <script>
      function RadioOption({ id, value, label, checked = false }) {
        return `
          <label class="option" for="${id}">
            <input
              id="${id}"
              type="radio"
              name="notification-preference"
              value="${value}"
              ${checked ? "checked" : ""}
              required
            >
            <span>${label}</span>
          </label>
        `;
      }

      function App() {
        return `
          <main id="main" class="page">
            <section class="card" aria-labelledby="page-title">
              <h1 id="page-title">Notification preferences</h1>
              <p class="lede">Choose one way you would like to receive updates.</p>

              <form>
                <div class="form-field">
                  <fieldset aria-describedby="notification-help">
                    <legend>
                      How do you prefer to receive notifications?
                      <span class="required-mark" aria-hidden="true">*</span>
                    </legend>
                    <p id="notification-help" class="help-text">Select one option before sending the form.</p>
                    <div class="options">
                      ${RadioOption({
                        id: "notification-email",
                        value: "email",
                        label: "Email"
                      })}
                      ${RadioOption({
                        id: "notification-sms",
                        value: "sms",
                        label: "SMS"
                      })}
                      ${RadioOption({
                        id: "notification-push",
                        value: "push",
                        label: "Push Notifications"
                      })}
                    </div>
                  </fieldset>
                </div>

                <div class="actions">
                  <button type="submit">Save preferences</button>
                </div>
              </form>
            </section>
          </main>
        `;
      }

      const app = document.getElementById("app");
      if (!app.children.length) {
        app.innerHTML = App();
      }
    </script>
  </body>
</html>
