 <!doctype html>
 <html lang="en">
   <head>
     <meta charset="utf-8">
     <meta name="viewport" content="width=device-width, initial-scale=1">
     <title>Notification Preferences</title>
     <style>
       :root {
         color-scheme: dark;
         --bg: #0b1220;
         --surface: #111a2e;
         --surface-2: #16233d;
         --border: #2b3b5f;
         --border-strong: #5b7cff;
         --text: #e8eefc;
         --muted: #a8b4d3;
         --accent: #7c9cff;
         --accent-2: #97a6ff;
         --focus: #f7c948;
         --shadow: 0 24px 60px rgba(0, 0, 0, 0.35);
       }

       * {
         box-sizing: border-box;
       }

       html {
         font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
         background:
           radial-gradient(circle at top, rgba(92, 124, 255, 0.18), transparent 36%),
           linear-gradient(180deg, #09101d 0%, var(--bg) 100%);
         color: var(--text);
       }

       body {
         margin: 0;
         min-height: 100vh;
         color: var(--text);
       }

       .skip-link {
         position: absolute;
         left: 1rem;
         top: -3rem;
         z-index: 10;
         padding: 0.75rem 1rem;
         border-radius: 0.75rem;
         background: #ffffff;
         color: #111827;
         text-decoration: none;
         font-weight: 600;
       }

       .skip-link:focus {
         top: 1rem;
         outline: 3px solid var(--focus);
         outline-offset: 3px;
       }

       .page {
         min-height: 100vh;
         display: grid;
         place-items: center;
         padding: 2rem 1rem;
       }

       .card {
         width: min(100%, 44rem);
         padding: clamp(1.5rem, 4vw, 2.5rem);
         border: 1px solid rgba(122, 143, 198, 0.25);
         border-radius: 1.5rem;
         background: linear-gradient(180deg, rgba(17, 26, 46, 0.98), rgba(10, 16, 30, 0.98));
         box-shadow: var(--shadow);
       }

       h1 {
         margin: 0 0 0.5rem;
         font-size: clamp(1.75rem, 3.5vw, 2.4rem);
         line-height: 1.1;
         letter-spacing: -0.02em;
       }

       .lede {
         margin: 0 0 1.75rem;
         color: var(--muted);
         line-height: 1.6;
       }

       form {
         display: grid;
         gap: 1.25rem;
       }

       .form-field {
         padding: 1.25rem;
         border: 1px solid rgba(122, 143, 198, 0.2);
         border-radius: 1.125rem;
         background: rgba(255, 255, 255, 0.02);
       }

       fieldset {
         margin: 0;
         padding: 0;
         border: 0;
       }

       legend {
         margin-bottom: 0.5rem;
         font-size: 1.05rem;
         font-weight: 700;
       }

       .required-mark {
         color: var(--accent-2);
       }

       .help-text {
         margin: 0 0 1rem;
         color: var(--muted);
         font-size: 0.95rem;
       }

       .options {
         display: grid;
         gap: 0.75rem;
       }

       .option {
         display: flex;
         align-items: center;
         gap: 0.8rem;
         padding: 0.9rem 1rem;
         border: 1px solid var(--border);
         border-radius: 0.9rem;
         background: rgba(255, 255, 255, 0.02);
         cursor: pointer;
         transition: border-color 0.2s ease, background-color 0.2s ease, transform 0.2s ease;
       }

       .option:hover {
         background: rgba(124, 156, 255, 0.08);
         border-color: rgba(124, 156, 255, 0.45);
       }

       .option:focus-within {
         background: rgba(124, 156, 255, 0.12);
         border-color: rgba(124, 156, 255, 0.7);
         outline: 3px solid var(--focus);
         outline-offset: 3px;
       }

       .option input {
         width: 1.125rem;
         height: 1.125rem;
         margin: 0;
         accent-color: var(--accent);
         flex: 0 0 auto;
       }

       .option span {
         font-size: 1rem;
         line-height: 1.4;
       }

       .actions {
         display: flex;
         justify-content: flex-end;
       }

       button {
         appearance: none;
         border: 1px solid rgba(124, 156, 255, 0.65);
         border-radius: 999px;
         padding: 0.9rem 1.3rem;
         background: linear-gradient(180deg, var(--accent), #5f7cff);
         color: #08101f;
         font: inherit;
         font-weight: 700;
         cursor: pointer;
         box-shadow: 0 10px 24px rgba(95, 124, 255, 0.3);
       }

       button:hover {
         filter: brightness(1.05);
       }

       button:focus-visible {
         outline: 3px solid var(--focus);
         outline-offset: 3px;
       }

       @media (max-width: 480px) {
         .page {
           padding: 1rem;
         }

         .card {
           border-radius: 1.1rem;
         }

         .form-field {
           padding: 1rem;
         }

         .actions {
           justify-content: normal;
         }

         button {
           width: 100%;
         }
       }

       @media (forced-colors: active) {
         .card,
         .form-field,
         .option,
         button {
           forced-color-adjust: auto;
         }
       }
     </style>
   </head>
   <body>
     <a class="skip-link" href="#main">Skip to main content</a>
     <div id="app">
       <main id="main" class="page">
         <section class="card" aria-labelledby="page-title">
           <h1 id="page-title">Notification preferences</h1>
           <p class="lede">Choose one way you would like to receive updates.</p>

           <form>
             <div class="form-field">
               <fieldset aria-describedby="notification-help">
                 <legend>
                   How do you prefer to receive notifications?
                   <span class="required-mark" aria-hidden="true">*</span>
                 </legend>
                 <p id="notification-help" class="help-text">Select one option before sending the form.</p>
                 <div class="options">
                   <label class="option" for="notification-email">
                     <input
                       id="notification-email"
                       type="radio"
                       name="notification-preference"
                       value="email"
                       required
                     >
                     <span>Email</span>
                   </label>
                   <label class="option" for="notification-sms">
                     <input
                       id="notification-sms"
                       type="radio"
                       name="notification-preference"
                       value="sms"
                       required
                     >
                     <span>SMS</span>
                   </label>
                   <label class="option" for="notification-push">
                     <input
                       id="notification-push"
                       type="radio"
                       name="notification-preference"
                       value="push"
                       required
                     >
                     <span>Push Notifications</span>
                   </label>
                 </div>
               </fieldset>
             </div>

             <div class="actions">
               <button type="submit">Save preferences</button>
             </div>
           </form>
         </section>
       </main>
     </div>

     <script>
       function RadioOption({ id, value, label, checked = false }) {
         return `
           <label class="option" for="${id}">
             <input
               id="${id}"
               type="radio"
               name="notification-preference"
               value="${value}"
               ${checked ? "checked" : ""}
               required
             >
             <span>${label}</span>
           </label>
         `;
       }

       function App() {
         return `
           <main id="main" class="page">
             <section class="card" aria-labelledby="page-title">
               <h1 id="page-title">Notification preferences</h1>
               <p class="lede">Choose one way you would like to receive updates.</p>

               <form>
                 <div class="form-field">
                   <fieldset aria-describedby="notification-help">
                     <legend>
                       How do you prefer to receive notifications?
                       <span class="required-mark" aria-hidden="true">*</span>
                     </legend>
                     <p id="notification-help" class="help-text">Select one option before sending the form.</p>
                     <div class="options">
                       ${RadioOption({
                         id: "notification-email",
                         value: "email",
                         label: "Email"
                       })}
                       ${RadioOption({
                         id: "notification-sms",
                         value: "sms",
                         label: "SMS"
                       })}
                       ${RadioOption({
                         id: "notification-push",
                         value: "push",
                         label: "Push Notifications"
                       })}
                     </div>
                   </fieldset>
                 </div>

                 <div class="actions">
                   <button type="submit">Save preferences</button>
                 </div>
               </form>
             </section>
           </main>
         `;
       }

       const app = document.getElementById("app");
       if (!app.children.length) {
         app.innerHTML = App();
       }
     </script>
   </body>
 </html>

')
